#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# ── Arcula dev environment, first run ─────────────────────────────────────
#
# The interactive half of infra/cdk/README.md's "First run", for dev. It is
# the one place the console work a human must do is written down as steps in
# the order they must happen, and it captures each value where it belongs.
#
# Nothing here provisions AWS except dev's certificate. The console work —
# the Supabase project, the Resend key, the Porkbun records — is the
# human's. The deploys are dispatched from the pipeline, never from a
# laptop. Production is touched exactly twice, in stages 11 and 12: its
# Environment secrets, and the release that deploys it.
#
# Values land in dev's own file, infra/cdk/.env.dev (gitignored, mode 0600),
# and on the `dev` GitHub Environment, which is restricted to the dev
# branch. Production's file is read, never written. Safe to re-run: an
# existing value is offered as the default and every gh write is an upsert.

ROOT=$(cd "$(dirname "$0")/.." && pwd)

# gh pages its output through $PAGER when stdout is a terminal. A wizard is a
# sequence of prompts, not a reader: on a machine with PAGER=less, stage 5's
# two Environment listings each opened less, so the run needed one "q" per
# listing before it could ask anything. Nothing printed here is longer than a
# screen. Exported, so every gh call in this run is covered and the caller's
# own PAGER is left alone.
export GH_PAGER=cat

# Dev has its own file and no fallback to production's — the rule
# scripts/environment.sh enforces, so a dev deploy can never read
# production's database URL or auth secret. Production's file path and its
# stack name come from that same file rather than from a copy here.
ENV_FILE="$ROOT/infra/cdk/.env.dev"
PROD_STACK=$(cd "$ROOT" && ENV=prod ROOT="$ROOT" sh -c '. "$ROOT/scripts/environment.sh"; printf "%s" "$STACK_NAME"')
PROD_ENV_FILE=$(cd "$ROOT" && ENV=prod ROOT="$ROOT" sh -c '. "$ROOT/scripts/environment.sh"; printf "%s" "$ENV_FILE"')

DEV_HOST="dev.arcula.art"
DEV_ZONE="arcula.art"

# The sender, display name and all. scripts/deploy.sh keeps each CDK
# context value one argument, so the spaces and angle brackets survive into
# the Lambda's EMAIL_FROM as written.
EMAIL_FROM="Arcula dev <noreply@dev.arcula.art>"

REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || true)
[[ -n "$REPO" ]] || REPO="<owner>/<repo>"

TEMPLATE_BEFORE=$(mktemp)
TEMPLATE_AFTER=$(mktemp)
trap 'rm -f "$TEMPLATE_BEFORE" "$TEMPLATE_AFTER"' EXIT

# _env_write secret|variable ENVIRONMENT NAME VALUE is one write to a
# GitHub Environment. It is one function rather than two because the
# library's set_secret/set_var write repository scopes, and the deploys read
# only the branch-scoped Environment: every value below takes this path.
_env_write() {
  local kind="$1" env_name="$2" name="$3" value="${4:-}" ok=""
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if [[ "$kind" == secret ]]; then
      if printf '%s' "$value" | gh secret set "$name" --env "$env_name" >/dev/null 2>&1; then ok=1; fi
    elif gh variable set "$name" --env "$env_name" --body "$value" >/dev/null 2>&1; then
      ok=1
    fi
  fi
  if [[ -n "$ok" ]]; then
    WRITTEN_SECRET+=("$env_name $kind $name")
    printf '  %s✓ set%s %s %s on the %s Environment\n' "$GREEN" "$RESET" "$kind" "$name" "$env_name"
    return 0
  fi
  SKIPPED+=("$env_name $kind $name — later: gh $kind set $name --env $env_name")
  warn "skipped $name ($kind) on $env_name: gh not ready"
  return 1
}

set_env_secret() { _env_write secret "$1" "$2" "$3"; }
set_env_var() { _env_write variable "$1" "$2" "$3"; }

# environment_facts ENVIRONMENT prints the branches an Environment admits,
# or "unrestricted". #5's isolation rests on that coupling: the dev
# Environment is readable only by dev, production's only by main.
environment_facts() {
  local env_name="$1" policy
  policy=$(gh api "repos/$REPO/environments/$env_name/deployment-branch-policies" \
    --jq '[.branch_policies[]? | .name] | join(", ")' 2>/dev/null) || policy="?"
  printf '%s' "${policy:-unrestricted}"
}

# require_environment ENVIRONMENT BRANCH warns, loudly and in the closing
# summary, when an Environment admits any branch but its own — the failure
# that would let one deploy read the other's secrets. The repository API
# cannot set the policy, so this reports rather than fixes.
require_environment() {
  local env_name="$1" branch="$2" policy
  policy=$(environment_facts "$env_name")
  if [[ "$policy" == "$branch" ]]; then
    note "$env_name Environment: restricted to $branch"
    return 0
  fi
  warn "$env_name Environment admits '$policy' — it must admit $branch alone."
  warn "Settings → Environments → $env_name → Deployment branches → 'Selected branches' → add $branch."
  SKIPPED+=("$env_name Environment branch restriction (currently: $policy)")
}

# prod_value KEY reads production's value for KEY from infra/cdk/.env in a
# subshell, so nothing the file holds enters this process and nothing is
# echoed. Empty when the file or the key is absent.
prod_value() {
  local key="$1"
  [ -f "$PROD_ENV_FILE" ] || { printf ''; return 0; }
  (
    set -a
    # shellcheck disable=SC1090
    . "$PROD_ENV_FILE" >/dev/null 2>&1
    set +a
    eval 'printf "%s" "${'"$key"':-}"'
  )
}

TOTAL_STAGES=13

banner "Arcula dev environment — first run"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Dev database — Supabase"
say "Dev gets its own Postgres project: the same provider and region as production, with data of its own."
open_url "https://supabase.com/dashboard/projects"
step "Open production's project → Settings → General and note its region — pick the same one."
step "New project → the same organisation → that region → set a database password → Create."
step "Wait for the project to finish provisioning."
step "Open the new project → Connect (or Settings → Database) → Connection string → URI."
step "Copy it in the flavour production uses — the Session pooler string if the Lambda has no IPv6."
note "It looks like postgres://postgres.<ref>:<password>@aws-0-<region>.pooler.supabase.com:5432/postgres"
ask_secret DATABASE_URL "Paste dev's connection string:"
write_env DATABASE_URL "$DATABASE_URL"
set_env_secret dev DATABASE_URL "$DATABASE_URL"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Dev mail — its own Resend key and sender"
say "Dev mails from its own key and its own sending subdomain, so dev mail is obvious and revoking the dev key cannot touch production's."
open_url "https://resend.com/domains"
step "Add domain → enter dev.arcula.art → Add."
step "Publish every record Resend shows for it (MX and TXT for SPF, a CNAME for DKIM) in Porkbun, under the arcula.art zone."
step "Back in Resend, click Verify and wait for 'Verified'."
open_url "https://resend.com/api-keys"
step "Create API key → name it 'arcula dev' → Permission: Sending access → Domain: dev.arcula.art → Create."
ask_secret RESEND_API_KEY "Paste the dev API key:"
note "Sender: $EMAIL_FROM"
write_env RESEND_API_KEY "$RESEND_API_KEY"
write_env EMAIL_FROM "$EMAIL_FROM"
set_env_secret dev RESEND_API_KEY "$RESEND_API_KEY"
set_env_var dev EMAIL_FROM "$EMAIL_FROM"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Dev auth secret"
say "A secret of dev's own, so a session minted on one environment can never be a valid session on the other."
AUTH_SECRET=$(openssl rand -base64 32 2>/dev/null || head -c 32 /dev/urandom | base64 | tr -d '\n')
note "Generated 32 random bytes; the value is never echoed."
write_env AUTH_SECRET "$AUTH_SECRET"
set_env_secret dev AUTH_SECRET "$AUTH_SECRET"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Dev owner account"
say "Every dev deploy seeds this account, so a freshly migrated dev database is immediately signable-in-able."
ask SEED_EMAIL "Owner email:"
ask SEED_NAME "Owner display name:"
ask_secret SEED_PASSWORD "Owner password (8+ characters):"
write_env SEED_EMAIL "$SEED_EMAIL"
write_env SEED_NAME "$SEED_NAME"
write_env SEED_PASSWORD "$SEED_PASSWORD"
set_env_var dev SEED_EMAIL "$SEED_EMAIL"
set_env_var dev SEED_NAME "$SEED_NAME"
set_env_secret dev SEED_PASSWORD "$SEED_PASSWORD"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Write dev's origin, and confirm the Environment"
DOMAIN="$DEV_HOST"
write_env DOMAIN "$DOMAIN"
set_env_var dev DOMAIN "$DOMAIN"
note "dev's deploy file: $ENV_FILE (gitignored, never committed)"
note "The run's own commit reaches the Lambda as DEPLOYED_COMMIT, handed over by the workflow — it is not stored anywhere."
say "The dev Environment's role was provisioned by scripts/provision-oidc.mjs; AWS_DEPLOY_ROLE must name it."
say "Here is everything the dev Environment holds now:"
gh api "repos/$REPO/environments/dev/variables" \
  --jq '.variables[] | "     variable  \(.name)"' 2>/dev/null ||
  warn "could not read the dev Environment's variables"
gh api "repos/$REPO/environments/dev/secrets" \
  --jq '.secrets[] | "     secret    \(.name)"' 2>/dev/null ||
  warn "could not read the dev Environment's secrets"
if ! gh api "repos/$REPO/environments/dev/variables/AWS_DEPLOY_ROLE" --jq .value >/dev/null 2>&1; then
  # Asked of IAM, not of provision-oidc.mjs: the script rewrites both roles
  # as it prints them, and a read sets nothing.
  AWS_DEPLOY_ROLE=$(aws iam get-role --role-name ArculaDeployDev \
    --query 'Role.Arn' --output text 2>/dev/null || true)
  if [[ -n "$AWS_DEPLOY_ROLE" ]]; then
    warn "AWS_DEPLOY_ROLE is not set on the dev Environment; setting it to $AWS_DEPLOY_ROLE"
    set_env_var dev AWS_DEPLOY_ROLE "$AWS_DEPLOY_ROLE"
  else
    warn "AWS_DEPLOY_ROLE is not set and ArculaDeployDev could not be read:"
    warn "run node scripts/provision-oidc.mjs, then set AWS_DEPLOY_ROLE on the dev Environment."
    SKIPPED+=("dev Environment AWS_DEPLOY_ROLE")
  fi
fi
say "The isolation this relies on is that each Environment admits only its own branch:"
require_environment dev dev
require_environment production main
pause "Press Enter to continue."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Dev certificate — ACM, validated by DNS"
say "An ACM certificate in us-east-1, the one region an API-Gateway HTTP-API custom domain can use."
say "The next command requests it, prints the validation record, then polls until ACM shows ISSUED."
open_url "https://porkbun.com/account/dns/$DEV_ZONE"
step "Keep the Porkbun DNS page open — publish the CNAME the command prints."
CERT_LOG=$(mktemp)
if ( cd "$ROOT" && node scripts/provision-cert.mjs "$DEV_HOST" 2>&1 | tee "$CERT_LOG" ); then
  CERT_ARN=$(grep -o 'certificate issued: .*' "$CERT_LOG" | tail -n1 | awk '{print $3}' || true)
else
  warn "provision-cert did not finish; re-run it — it reuses the same certificate."
  warn "If it named a credential or permission error, fix that before re-running:"
  warn "a pasted ARN cannot stand in for it, and the cert still has to be validated."
  CERT_ARN=""
fi
rm -f "$CERT_LOG"
[[ -n "$CERT_ARN" ]] || ask CERT_ARN "Paste the certificate ARN:"
write_env CERT_ARN "$CERT_ARN"
set_env_var dev CERT_ARN "$CERT_ARN"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "First dev deploy — from the pipeline"
say "Merging to dev deploys dev; this dispatches that same workflow by hand."
say "Command: gh workflow run deploy-dev.yml --ref dev"
open_url "https://github.com/$REPO/actions/workflows/deploy-dev.yml"
pause "Press Enter once the run has finished."
say "Expected: the gate passes, the artifact builds, ArculaDev is deployed, migrations and the seed run against dev's database, and then it stops with"
note "  dev.arcula.art does not resolve yet — publish these Porkbun records"
say "and finishes successfully. That exit is the design: the first deploy of an environment must not be stuck behind a console step."
say "It prints an 'apex' line and, because the stack derives a www pair for any domain, a 'www.…' line as well. dev publishes only the apex."
ask ROUTING_RECORD "Paste that output's 'apex' line:"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Publish dev's routing record"
open_url "https://porkbun.com/account/dns/$DEV_ZONE"
say "The deploy printed:"
note "     $ROUTING_RECORD"
step "Add record → Type: CNAME → Host: dev → Answer: the d-… value in that line → TTL 600 → Add."
note "To use Porkbun's ALIAS instead, the answer is the same d-… value and the zone id is the one in that line."
note "No www record: dev has one host, so nothing else needs to answer."
pause "Press Enter once the record is saved."

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Re-run the deploy — the end-to-end verify runs"
say "Now that the host resolves, the same workflow continues past the DNS gate and verifies."
say "Command: gh workflow run deploy-dev.yml --ref dev"
open_url "https://github.com/$REPO/actions/workflows/deploy-dev.yml"
pause "Press Enter once the run is green."
say "Expected, the whole pass green: health, the SPA shell and a deep link, sign-up with a Secure session cookie, the duplicate sign-up's 422,"
say "a collection create, the tier cap's 409, a real 12 MP photo through stage → process → save, a visitor read, and the reset-mail path."

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Confirm the dev-only responses, and production's"
say "Dev must stay out of search results; production's responses must be untouched by the mechanism."
say "Dev's gate, before the pipeline — the full pass, exactly what the workflow just ran:"
say "Command: cd apps/api && bun scripts/deploy-verify.ts https://$DEV_HOST"
say "Probes, for the parts a collector sees:"
printf '     X-Robots-Tag on https://%s/ : ' "$DEV_HOST"
curl -sI "https://$DEV_HOST/" 2>/dev/null | tr -d '\r' | grep -i '^x-robots-tag:' ||
  warn "no X-Robots-Tag header — is the deploy live?"
printf '     %s/robots.txt : ' "$DEV_HOST"
curl -s "https://$DEV_HOST/robots.txt" 2>/dev/null | tr '\n' ' ' || true
printf '\n'
printf '     %s/api/health : ' "$DEV_HOST"
curl -s "https://$DEV_HOST/api/health" 2>/dev/null || true
printf '\n'
printf '     arcula.art/api/health : '
curl -s "https://arcula.art/api/health" 2>/dev/null || true
printf '\n'
say "Expect: X-Robots-Tag: noindex, a disallow-all robots.txt, dev's body carrying the deployed commit, and production's carrying only {\"status\":\"ok\"}."
pause "Press Enter to continue."

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Production's Environment configuration"
say "The release below deploys production through the pipeline, and production's workflow reads only the production Environment."
say "Secrets come from $PROD_ENV_FILE (production's own file) and are never echoed; the public values are the ones this run already holds."
if [ -f "$PROD_ENV_FILE" ]; then
  note "found $PROD_ENV_FILE"
else
  warn "missing $PROD_ENV_FILE — set production's secrets by hand"
fi
if confirm "Set production's secrets and public values now?"; then
  for name in DATABASE_URL AUTH_SECRET RESEND_API_KEY; do
    value=$(prod_value "$name")
    if [[ -n "$value" ]]; then
      set_env_secret production "$name" "$value"
    else
      SKIPPED+=("production secret $name (empty in $PROD_ENV_FILE)")
      warn "$name is empty in $PROD_ENV_FILE"
    fi
  done
  # DOMAIN and CERT_ARN are the difference between the live stack and a
  # stack with no custom domain: an empty DOMAIN drops both DomainName pairs
  # from the template, which is not a change production may take.
  for name in DOMAIN CERT_ARN; do
    value=$(prod_value "$name")
    if [[ -n "$value" ]]; then
      set_env_var production "$name" "$value"
    else
      SKIPPED+=("production variable $name (empty in $PROD_ENV_FILE)")
      warn "$name is empty in $PROD_ENV_FILE — production would deploy without its domain"
    fi
  done
  PROD_EMAIL_FROM=$(prod_value EMAIL_FROM)
  set_env_var production EMAIL_FROM "${PROD_EMAIL_FROM:-noreply@arcula.art}"
  ask PROD_SEED_EMAIL "Production owner email:" "$(prod_value SEED_EMAIL)"
  set_env_var production SEED_EMAIL "$PROD_SEED_EMAIL"
  ask PROD_SEED_NAME "Production owner display name:" "$(prod_value SEED_NAME)"
  set_env_var production SEED_NAME "$PROD_SEED_NAME"
  say "SEED_PASSWORD only matters to a database with no owner yet: the seed reports an existing account rather than updating it, so this value cannot change the live login."
  ask_secret SEED_PASSWORD_PROD "Production owner password (any value):"
  [[ -n "$SEED_PASSWORD_PROD" ]] && set_env_secret production SEED_PASSWORD "$SEED_PASSWORD_PROD"
fi

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Release — a merge commit from dev into main"
say "Merging this PR into main is the release: it deploys production through the pipeline."
say "First, capture production's template as it stands, so the release can be held to not disturbing it."
if aws cloudformation get-template --stack-name "$PROD_STACK" --query TemplateBody --output json > "$TEMPLATE_BEFORE" 2>/dev/null; then
  note "captured $(wc -c < "$TEMPLATE_BEFORE" | tr -d ' ') bytes"
else
  warn "could not read $PROD_STACK's template — the comparison in the next stage will be skipped"
fi
say "Command: gh pr create --base main --head dev --title 'Release: …'"
open_url "https://github.com/$REPO/compare/main...dev"
step "Open the PR and review what main does not have."
step "Merge it with a merge commit — never squash, so main keeps one commit per release."
say "Command: gh pr merge <number> --merge"
open_url "https://github.com/$REPO/actions/workflows/deploy-prod.yml"
pause "Press Enter once the production deploy is green."

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Prove the release did not disturb production's resources"
if [[ -s "$TEMPLATE_BEFORE" ]] &&
  aws cloudformation get-template --stack-name "$PROD_STACK" --query TemplateBody --output json > "$TEMPLATE_AFTER" 2>/dev/null; then
  if diff -u "$TEMPLATE_BEFORE" "$TEMPLATE_AFTER" >/dev/null; then
    say "Byte-identical: the release did not perturb production."
  else
    warn "the template differs — read the diff below."
    warn "The stack Description is the expected difference: it is the text the two environments were named apart with,"
    warn "and it changes the console's label for the stack, not anything CloudFormation creates."
    warn "CDKMetadata's analytics blob may differ with the CDK version. Anything else — a resource added, removed or replaced — is a real change."
    diff -u "$TEMPLATE_BEFORE" "$TEMPLATE_AFTER" | head -n 60 || true
  fi
else
  warn "no template captured to compare against"
fi
say "The pipeline already ran the same pass against production; this is the same one from outside it:"
say "Command: cd apps/api && bun scripts/deploy-verify.ts https://arcula.art"
say "And a collector's view, unchanged:"
open_url "https://arcula.art"

finish
}

run_wizard "$@"; exit
